package android.os;import java.util.*;public class Handler {public static final List<Runnable> pending=new ArrayList<>();public Handler(Looper l){}public boolean post(Runnable r){pending.add(r);return true;}public static final List<Runnable> delayed=new ArrayList<>();public boolean postDelayed(Runnable r,long d){if(d==1500)delayed.add(r);return true;}public static void flushDelayed(){while(!delayed.isEmpty())delayed.remove(0).run();flush();}public void removeCallbacksAndMessages(Object o){}public void removeCallbacks(Runnable r){}public Looper getLooper(){return Looper.MAIN;}public static void flush(){int count=0;while(!pending.isEmpty()){if(count++>1000)throw new AssertionError("loop");pending.remove(0).run();}}}
